export default function links({ record }) {
  const f = record?.fields;
  if (!f || typeof record.id !== "string" || !record.id) throw Error("Invalid automation record");
  function one(name) {
    const a = f[name];
    if (!Array.isArray(a) || typeof a[0] !== "string" || !a[0])
      throw Error(`Missing ${name} linked record`);
    return a[0];
  }
  return {
    templateId: one("Template"),
    assigneeId: one("Assigned Team Member"),
    clientId: one("Client"),
  };
}

